--Challenge C-06: Salesperson Effectiveness

--1: Top & Bottom Performers

SELECT 
    salesperson_id,
    
    COUNT(DISTINCT invoice_id) AS transactions,
    ROUND(CAST(SUM(total_amount)AS NUMERIC),2) AS revenue,
    ROUND(CAST(SUM(gross_weight)AS NUMERIC),2) AS weight

FROM vw_sales_clean
WHERE is_return = false
GROUP BY salesperson_id
ORDER BY revenue DESC
LIMIT 10;

--2: Avg Transaction Value

SELECT 
    salesperson_id,
    
    ROUND(CAST(
        SUM(total_amount) / COUNT(DISTINCT invoice_id)AS NUMERIC), 2
    ) AS avg_transaction_value

FROM vw_sales_clean
WHERE is_return = false
GROUP BY salesperson_id
ORDER BY avg_transaction_value DESC;

