--3: Return Rate by Salesperson

SELECT 
    salesperson_id,
    
    ROUND(
        COUNT(CASE WHEN is_return = true THEN 1 END) * 100.0
        / COUNT(*), 2
    ) AS return_rate

FROM vw_sales_clean
GROUP BY salesperson_id
ORDER BY return_rate DESC;
