--4: Karat Mix by Salesperson

SELECT 
    salesperson_id,
    
    CASE 
        WHEN purity >= 0.90 THEN '22K+'
        ELSE 'Lower Karat'
    END AS karat_group,
    
    SUM(total_amount) AS revenue

FROM vw_sales_clean
WHERE is_return = false
GROUP BY salesperson_id, karat_group
