--Old Gold Driven Sales

SELECT 
    s.salesperson_id,
    COUNT(DISTINCT og.customer_id) AS og_customers

FROM fact_old_gold_purchase og
JOIN vw_sales_clean s
    ON og.customer_id = s.customer_id

GROUP BY s.salesperson_id
ORDER BY og_customers  limit 10;
