--6: Discount Behavior
SELECT 
    salesperson_id,
    ROUND(CAST(AVG(discount)AS NUMERIC),2) AS avg_discount

FROM vw_sales_clean
GROUP BY salesperson_id
ORDER BY avg_discount DESC;

